DROP DATABASE IF EXISTS smart_zone;
CREATE DATABASE smart_zone;
use smart_zone ;
-- 1. customers
CREATE TABLE customers (
    customer_id        INT             AUTO_INCREMENT PRIMARY KEY,
    name                VARCHAR(100)    NOT NULL,
    gender              VARCHAR(10),
    age                 INT,
    city                VARCHAR(50),
    customer_segment    VARCHAR(50),
    registration_date   DATE
);
-- 2. products
CREATE TABLE products (
    product_id      INT             AUTO_INCREMENT PRIMARY KEY,
    product_name    VARCHAR(100)    NOT NULL,
    brand           VARCHAR(50),
    category        VARCHAR(50),
    unit_cost       DECIMAL(10,2)   NOT NULL,
    unit_price      DECIMAL(10,2)   NOT NULL,
    stock_quantity  INT             NOT NULL,
    product_rating  DECIMAL(3,2)
);
-- 3. stores
CREATE TABLE stores (
    store_id        INT             AUTO_INCREMENT PRIMARY KEY,
    store_name      VARCHAR(100)    NOT NULL,
    city            VARCHAR(50),
    region          VARCHAR(50),
    store_type      VARCHAR(50),
    opening_date    DATE
);
-- 4. employees
CREATE TABLE employees (
    employee_id     INT             AUTO_INCREMENT PRIMARY KEY,
    name            VARCHAR(100)    NOT NULL,
    gender          VARCHAR(10),
    hire_date       DATE,
    job_title       VARCHAR(50),
    store_id        INT             NOT NULL,
    CONSTRAINT fk_employees_store
        FOREIGN KEY (store_id) REFERENCES stores(store_id)
);
-- 5. sales
CREATE TABLE sales (
    sale_id         INT             AUTO_INCREMENT PRIMARY KEY,
    sale_date       DATE            NOT NULL,
    payment_method  VARCHAR(50),
    order_status    VARCHAR(50),
    customer_id     INT             NOT NULL,
    store_id        INT             NOT NULL,
    employee_id     INT             NOT NULL,
    CONSTRAINT fk_sales_customer
        FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    CONSTRAINT fk_sales_store
        FOREIGN KEY (store_id) REFERENCES stores(store_id),
    CONSTRAINT fk_sales_employee
        FOREIGN KEY (employee_id) REFERENCES employees(employee_id)
);
-- 6. sale_details (weak entity, composite PK, no AUTO_INCREMENT)
CREATE TABLE sale_details (
    sale_id         INT             NOT NULL,
    product_id      INT             NOT NULL,
    quantity        INT             NOT NULL,
    unit_price      DECIMAL(10,2)   NOT NULL,
    unit_cost       DECIMAL(10,2)   NOT NULL,
    discount        DECIMAL(10,2),
    PRIMARY KEY (sale_id, product_id),
    CONSTRAINT fk_saledetails_sale
        FOREIGN KEY (sale_id) REFERENCES sales(sale_id),
    CONSTRAINT fk_saledetails_product
        FOREIGN KEY (product_id) REFERENCES products(product_id)
);
ALTER TABLE customers DROP COLUMN customer_segment;
ALTER TABLE products DROP COLUMN stock_quantity;
ALTER TABLE stores
DROP COLUMN region,DROP COLUMN store_type;
