SELECT 'stores' AS table_name, COUNT(*) AS row_count
FROM stores

UNION ALL

SELECT 'employees', COUNT(*)
FROM employees

UNION ALL

SELECT 'customers', COUNT(*)
FROM customers

UNION ALL

SELECT 'products', COUNT(*)
FROM products

UNION ALL

SELECT 'sales', COUNT(*)
FROM sales

UNION ALL

SELECT 'sale_details', COUNT(*)
FROM sale_details;
SELECT 
    TABLE_NAME,
    COLUMN_NAME,
    DATA_TYPE,
    IS_NULLABLE,
    COLUMN_KEY,
    EXTRA
FROM information_schema.COLUMNS
WHERE TABLE_SCHEMA = 'smart_zone'
ORDER BY 
    FIELD(TABLE_NAME,
        'stores',
        'employees',
        'customers',
        'products',
        'sales',
        'sale_details'
    ),
    ORDINAL_POSITION;
    SELECT customer_id, COUNT(*) AS cnt
FROM customers
GROUP BY customer_id
HAVING COUNT(*) > 1;
SELECT product_id, COUNT(*) AS cnt
FROM products
GROUP BY product_id
HAVING COUNT(*) > 1;
SELECT employee_id, COUNT(*) AS cnt
FROM employees
GROUP BY employee_id
HAVING COUNT(*) > 1;
SELECT store_id, COUNT(*) AS cnt
FROM stores
GROUP BY store_id
HAVING COUNT(*) > 1;
SELECT sale_id, COUNT(*) AS cnt
FROM sales
GROUP BY sale_id
HAVING COUNT(*) > 1;
SELECT sale_id, product_id, COUNT(*) AS cnt
FROM sale_details
GROUP BY sale_id, product_id
HAVING COUNT(*) > 1;
SELECT e.*
FROM employees e
LEFT JOIN stores s
    ON e.store_id = s.store_id
WHERE s.store_id IS NULL;
SELECT s.*
FROM sales s
LEFT JOIN customers c
    ON s.customer_id = c.customer_id
WHERE c.customer_id IS NULL;
SELECT s.*
FROM sales s
LEFT JOIN stores st
    ON s.store_id = st.store_id
WHERE st.store_id IS NULL;
SELECT s.*
FROM sales s
LEFT JOIN employees e
    ON s.employee_id = e.employee_id
WHERE e.employee_id IS NULL;
SELECT sd.*
FROM sale_details sd
LEFT JOIN sales s
    ON sd.sale_id = s.sale_id
WHERE s.sale_id IS NULL;
SELECT sd.*
FROM sale_details sd
LEFT JOIN products p
    ON sd.product_id = p.product_id
WHERE p.product_id IS NULL;
SELECT 
    MIN(sale_date) AS first_sale,
    MAX(sale_date) AS last_sale
FROM sales;
SELECT *
FROM sales
WHERE sale_date < '2026-01-01'
   OR sale_date > '2026-06-30';
   SELECT
    YEAR(sale_date) AS year,
    MONTH(sale_date) AS month,
    COUNT(*) AS sales_count
FROM sales
GROUP BY YEAR(sale_date), MONTH(sale_date)
ORDER BY year, month;
SELECT
    store_id,
    store_name,
    city,
    opening_date
FROM stores
ORDER BY store_id;
SELECT
    s.store_name,
    s.city,
    COUNT(e.employee_id) AS employee_count
FROM stores s
LEFT JOIN employees e
    ON s.store_id = e.store_id
GROUP BY s.store_id, s.store_name, s.city
ORDER BY s.store_id;
SELECT name, COUNT(*) AS cnt
FROM customers
GROUP BY name
HAVING COUNT(*) > 1;
SELECT name, COUNT(*) AS cnt
FROM employees
GROUP BY name
HAVING COUNT(*) > 1;
SELECT
    category,
    COUNT(*) AS product_count
FROM products
GROUP BY category
ORDER BY product_count DESC;
SELECT
    brand,
    COUNT(*) AS product_count
FROM products
GROUP BY brand
ORDER BY product_count DESC;
SELECT
    product_id,
    COUNT(DISTINCT product_name) AS names,
    COUNT(DISTINCT brand) AS brands,
    COUNT(DISTINCT category) AS categories
FROM products
GROUP BY product_id
HAVING names > 1
    OR brands > 1
    OR categories > 1;
    SELECT *
FROM products
WHERE unit_cost >= unit_price;
SELECT
    MIN(discount) AS min_discount,
    MAX(discount) AS max_discount,
    AVG(discount) AS avg_discount
FROM sale_details;
SELECT
    s.sale_id,
    s.sale_date,
    st.store_id,
    st.opening_date
FROM sales s
JOIN stores st
    ON s.store_id = st.store_id
WHERE st.opening_date > s.sale_date;
SELECT payment_method, COUNT(*) AS count
FROM sales
GROUP BY payment_method
ORDER BY count DESC;
SELECT order_status, COUNT(*) AS count
FROM sales
GROUP BY order_status
ORDER BY count DESC;
SELECT
    SUM(payment_method IS NULL) AS payment_nulls,
    SUM(payment_method = '') AS payment_blanks,
    SUM(order_status IS NULL) AS status_nulls,
    SUM(order_status = '') AS status_blanks
FROM sales;
SELECT DISTINCT payment_method
FROM sales
ORDER BY payment_method;
SELECT DISTINCT order_status
FROM sales
ORDER BY order_status;
SELECT
    sale_date,
    customer_id,
    store_id,
    employee_id,
    payment_method,
    order_status,
    COUNT(*) AS duplicate_count
FROM sales
GROUP BY
    sale_date,
    customer_id,
    store_id,
    employee_id,
    payment_method,
    order_status
HAVING COUNT(*) > 1
ORDER BY duplicate_count DESC;
SELECT
    MONTH(sale_date) AS month,
    COUNT(*) AS sales_count
FROM sales
GROUP BY MONTH(sale_date)
ORDER BY month;
SELECT
    SUM(name IS NULL) AS name_nulls,
    SUM(gender IS NULL) AS gender_nulls,
    SUM(city IS NULL) AS city_nulls,
    SUM(age IS NULL) AS age_nulls,
    SUM(registration_date IS NULL) AS date_nulls
FROM customers;
SELECT DISTINCT gender
FROM customers
ORDER BY gender;
SELECT DISTINCT city
FROM customers
ORDER BY city;
SELECT DISTINCT brand
FROM products
ORDER BY brand;
SELECT DISTINCT category
FROM products
ORDER BY category;
SELECT
    product_id,
    product_name,
    brand,
    category
FROM products
ORDER BY product_id;
SELECT
    product_id,
    COUNT(DISTINCT product_name) AS names,
    COUNT(DISTINCT brand) AS brands,
    COUNT(DISTINCT category) AS categories
FROM products
GROUP BY product_id
HAVING names > 1
    OR brands > 1
    OR categories > 1;
    SELECT
    COUNT(*) AS total_rows,
    SUM(quantity IS NULL) AS quantity_nulls,
    SUM(unit_price IS NULL) AS price_nulls,
    SUM(unit_cost IS NULL) AS cost_nulls,
    SUM(discount IS NULL) AS discount_nulls,
    MIN(quantity) AS min_quantity,
    MAX(quantity) AS max_quantity,
    MIN(unit_price) AS min_price,
    MAX(unit_price) AS max_price,
    MIN(unit_cost) AS min_cost,
    MAX(unit_cost) AS max_cost,
    MIN(discount) AS min_discount,
    MAX(discount) AS max_discount
FROM sale_details;
SELECT
    p.category,
    COUNT(sd.product_id) AS sale_lines,
    SUM(sd.quantity) AS total_quantity
FROM products p
JOIN sale_details sd
    ON p.product_id = sd.product_id
GROUP BY p.category
ORDER BY total_quantity DESC;
